mapper.select:
SELECT
    (
        SELECT COUNT(*) FROM customer c
        WHERE 1 = 1

            AND c.assigned_sales_id = #{ownerEmployeeId}

    ) AS total_customers,
    (
        SELECT COUNT(*) FROM customer c
        WHERE c.active = TRUE
          AND c.status = 'ACTIVE'

            AND c.assigned_sales_id = #{ownerEmployeeId}

    ) AS active_customers,
    (
        SELECT COUNT(*) FROM customer c
        WHERE c.active = TRUE
          AND c.status = 'PROSPECT'

            AND c.assigned_sales_id = #{ownerEmployeeId}

    ) AS prospect_customers,
    (
        SELECT COUNT(*) FROM sales_opportunity o
        WHERE o.status = 'OPEN'

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS open_opportunities,
    (
        SELECT COUNT(*) FROM sales_opportunity o
        WHERE o.stage = 'WON'

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS won_opportunities,
    (
        SELECT COUNT(*) FROM sales_opportunity o
        WHERE o.stage = 'LOST'

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS lost_opportunities,
    (
        SELECT COUNT(*) FROM sales_opportunity o
        WHERE o.status = 'OPEN'
          AND o.expected_close_date >= #{monthStart}
          AND o.expected_close_date < #{nextMonthStart}

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS closing_this_month,
    (
        SELECT COALESCE(SUM(o.expected_revenue), 0) FROM sales_opportunity o
        WHERE o.status = 'OPEN'

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS open_pipeline_amount,
    (
        SELECT COALESCE(SUM(o.expected_revenue * o.probability / 100), 0)
        FROM sales_opportunity o
        WHERE o.status = 'OPEN'

            AND o.owner_employee_id = #{ownerEmployeeId}

    ) AS weighted_pipeline_amount

SELECT o.stage, COUNT(*) AS stage_count FROM sales_opportunity o
AND o.owner_employee_id = #{ownerEmployeeId}
GROUP BY o.stage ORDER BY CASE o.stage WHEN 'LEAD' THEN 1 WHEN 'QUALIFIED' THEN 2 WHEN 'PROPOSAL' THEN 3 WHEN 'NEGOTIATION' THEN 4 WHEN 'WON' THEN 5 WHEN 'LOST' THEN 6 ELSE 99 END
